"""P1 — Vue Globale & KPIs"""import streamlit as stimport plotly.graph_objects as gofrom config import C, apply_theme, SAT_GLOBAL, PCT_INTERNATIONAL, to_rgbafrom components.kpi_cards import kpi_row, section_title, page_headerfrom data.loader import load_evolutiondef render():    page_header("Vue Globale",                "Chrono24 · 175 968 transactions · 2016–2020 · 67 pays acheteurs", "🌐")    df_evo = load_evolution()    kpi_row([        {"title": "Transactions analysées", "value": "175 968",         "subtitle": "2016 → 2020", "color": "blue", "icon": "📊"},        {"title": "Flux internationaux", "value": f"{PCT_INTERNATIONAL}%",         "subtitle": "des ventes", "color": "teal", "icon": "✈️"},        {"title": "Satisfaction moyenne", "value": f"{SAT_GLOBAL:.3f}/5",         "subtitle": "Note globale marché", "color": "green", "icon": "⭐"},        {"title": "Vendeurs actifs", "value": "2 309",         "subtitle": "Snapshot Avril 2020", "color": "purple", "icon": "🏪"},        {"title": "Pays impliqués", "value": "67 / 62",         "subtitle": "Acheteurs / Vendeurs", "color": "orange", "icon": "🌍"},    ])    col1, col2 = st.columns(2)    with col1:        section_title("Répartition Domestique / International")        fig = go.Figure(go.Pie(            labels=["International", "Domestique"],            values=[72.1, 27.9],            hole=0.58,            marker=dict(                colors=[C["blue"], C["card2"]],                line=dict(color=C["bg"], width=3)            ),            textinfo="label+percent",            textfont=dict(color=C["text"], size=12),            hovertemplate="%{label}<br><b>%{percent}</b><extra></extra>",        ))        fig.add_annotation(            text="<b>72.1%</b><br>International",            x=0.5, y=0.5, showarrow=False,            font=dict(size=16, color=C["blue"])        )        apply_theme(fig, "")        fig.update_layout(height=300, margin=dict(l=10, r=10, t=10, b=10),                          showlegend=False)        st.plotly_chart(fig, use_container_width=True)    with col2:        section_title("Satisfaction globale — évolution 5 ans")        fig2 = go.Figure()        fig2.add_trace(go.Scatter(            x=df_evo["Année"],            y=df_evo["Note globale"],            mode="lines+markers+text",            line=dict(color=C["green"], width=3),            marker=dict(size=9, color=C["green"],                        line=dict(color=C["bg"], width=2)),            text=[f"{v:.3f}" for v in df_evo["Note globale"]],            textposition="top center",            textfont=dict(color=C["text"], size=11),            fill="tozeroy",            fillcolor=to_rgba(C["green"], 0.13),            hovertemplate="<b>%{x}</b> → %{y:.3f}/5<extra></extra>",        ))        fig2.add_hline(            y=SAT_GLOBAL, line_dash="dash",            line_color=C["orange"], opacity=0.6,            annotation_text=f"Moy. {SAT_GLOBAL}",            annotation_font_color=C["orange"]        )        apply_theme(fig2, "")        fig2.update_layout(height=300, showlegend=False)        fig2.update_yaxes(range=[4.80, 4.84])        st.plotly_chart(fig2, use_container_width=True)    section_title("Insights clés", "💡")    col_a, col_b, col_c = st.columns(3)    insights = [        (C["blue"], "Marché hyper-mondialisé",         "72,1% des transactions croisent une frontière. L'Allemagne est le hub central : 30% des ventes et 19% des achats."),        (C["green"], "Satisfaction robuste",         "La note de 4,821/5 progresse chaque année (+0,021 pts sur 5 ans), malgré la croissance des volumes."),        (C["orange"], "L'international ne pénalise pas",         "Écart dom/intl = seulement 0,025 pts. Surprenant : l'intercontinental (4,821) dépasse l'intra-EU (4,809)."),    ]    for col, (color, title, text) in zip([col_a, col_b, col_c], insights):        with col:            st.markdown(f"""            <div style="background:{C['card']};border-left:3px solid {color};                        border-radius:8px;padding:14px;height:130px;">                <div style="font-size:13px;font-weight:600;color:{color};                            margin-bottom:8px;">{title}</div>                <div style="font-size:12px;color:{C['muted']};                            line-height:1.5;">{text}</div>            </div>""", unsafe_allow_html=True)    section_title("Volume de transactions par année", "📈")    fig3 = go.Figure(go.Bar(        x=df_evo["Année"],        y=df_evo["Nb transactions"],        marker=dict(            color=[C["blue"] if y < 2020 else C["orange"]                   for y in df_evo["Année"]],            opacity=0.85,            line=dict(color=C["bg"], width=1)        ),        text=[f"{int(v):,}" for v in df_evo["Nb transactions"]],        textposition="outside",        textfont=dict(color=C["text"]),        hovertemplate="<b>%{x}</b><br>%{y:,} transactions<extra></extra>",    ))    fig3.add_annotation(        x=2020,        y=df_evo[df_evo["Année"] == 2020]["Nb transactions"].values[0],        text="↓ Covid-19", showarrow=True, arrowhead=2,        arrowcolor=C["orange"],        font=dict(color=C["orange"], size=11), yshift=20    )    apply_theme(fig3, "")    fig3.update_layout(height=240, margin=dict(t=10, b=10))    st.plotly_chart(fig3, use_container_width=True)